  t = 5_000;
  d.save('ana', 'doc:1', 4, { body: 'Hello' });
  assert.equal(d.mine('ana')[0]!.history.length, 1, 'still the same snapshot');
  for (const [i, body] of ['Hello w', 'Hello wo', 'Hello wor', 'Hello world'].entries()) {
    t = 40_000 * (i + 1);
    d.save('ana', 'doc:1', 4, { body });
